package ipl.sable.dim; import java.util.*; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.Level; import net.minecraft.core.BlockPos; public class IplWorldFrameContext { private static ThreadLocal<ServerLevel> value=new ThreadLocal<>(); public static Map<BlockPos,ServerLevel> owners=new HashMap<>(); public static ServerLevel current(){return value.get();} public static ServerLevel push(ServerLevel v){var prev=value.get();value.set(v);return prev;} public static void pop(ServerLevel v){if(v==null)value.remove();else value.set(v);} public static ServerLevel resolveParentForPlotBe(Level l,BlockPos pos){return l.storage?owners.get(pos):null;} }